// Pre-normalizador determinista (DEC-003).
// Resuelve monto y fecha SIN llamar al LLM. La mayoria de los mensajes
// de texto se resuelven aqui: menos costo, menos latencia y menos
// superficie de prompt injection.

const sobre = $json;
const textoOriginal = String(sobre.payload?.texto || '');
const ZONA = 'America/Bogota';

// --- Normalizacion base ---
const t = textoOriginal
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')  // quita tildes
  .replace(/\s+/g, ' ')
  .trim();

// ---------- MONTO ----------
const UNIDADES = { cero:0, un:1, uno:1, una:1, dos:2, tres:3, cuatro:4, cinco:5, seis:6, siete:7, ocho:8, nueve:9, diez:10, once:11, doce:12, trece:13, catorce:14, quince:15, dieciseis:16, diecisiete:17, dieciocho:18, diecinueve:19, veinte:20, treinta:30, cuarenta:40, cincuenta:50, sesenta:60, setenta:70, ochenta:80, noventa:90, cien:100, ciento:100, doscientos:200, trescientos:300, cuatrocientos:400, quinientos:500, seiscientos:600, setecientos:700, ochocientos:800, novecientos:900 };

function numeroEnLetras(txt) {
  const palabras = txt.split(/[\s-]+/);
  let total = 0, parcial = 0, encontro = false;
  for (const p of palabras) {
    if (p === 'y') continue;
    if (UNIDADES[p] !== undefined) { parcial += UNIDADES[p]; encontro = true; }
    else if (p === 'mil') { parcial = (parcial || 1) * 1000; total += parcial; parcial = 0; encontro = true; }
    else if (p === 'millon' || p === 'millones') { parcial = (parcial || 1) * 1000000; total += parcial; parcial = 0; encontro = true; }
    else if (encontro && total + parcial > 0) break;
  }
  const r = total + parcial;
  return r > 0 ? r : null;
}

// Formato colombiano: el punto separa miles, la coma es decimal.
function aEntero(s) {
  let x = String(s).replace(/\s/g, '');
  if (x.includes(',')) x = x.split(',')[0];  // se ignoran centavos
  x = x.replace(/\./g, '');
  const n = parseInt(x, 10);
  return Number.isFinite(n) ? n : null;
}

const candidatos = [];
let confianzaMonto = 0;
let jerga = false;

// 1. "350 mil", "1.5 millones", "350k", "350 lucas"
const reMultiplicador = /(\d+(?:[.,]\d+)?)\s*(mil|millon|millones|k|lucas|barras|palos)\b/g;
let m;
while ((m = reMultiplicador.exec(t)) !== null) {
  const crudo = m[1];
  // "1.5 millones" es decimal; "1.500 mil" es separador de miles.
  // Se distinguen por cuantos digitos siguen al separador: 3 => miles.
  const base = /^\d+[.,]\d{1,2}$/.test(crudo)
    ? parseFloat(crudo.replace(',', '.'))
    : parseFloat(crudo.replace(/[.,]/g, ''));
  const u = m[2];
  const factor = (u === 'millon' || u === 'millones') ? 1000000 : 1000;
  if (['lucas', 'barras', 'palos'].includes(u)) jerga = true;
  candidatos.push(Math.round(base * factor));
}

// 2. Digitos sueltos: $350.000 / 350000 / COP 240000 / 85.500 pesos
if (candidatos.length === 0) {
  const reDigitos = /(?:\$|cop\s*)?\b(\d{1,3}(?:\.\d{3})+|\d{4,9})\b(?!\s*(?:mil|millon|millones|k|lucas))/g;
  while ((m = reDigitos.exec(t)) !== null) {
    const v = aEntero(m[1]);
    if (v !== null && v >= 100) candidatos.push(v);
  }
}

// 3. Numero escrito en letras
if (candidatos.length === 0) {
  const v = numeroEnLetras(t);
  if (v !== null && v >= 100) candidatos.push(v);
}

const unicos = [...new Set(candidatos)];
let monto = null;
let motivoConfirmacion = null;

if (unicos.length === 1) {
  monto = unicos[0];
  confianzaMonto = jerga ? 0.75 : 0.95;
} else if (unicos.length > 1) {
  // Dos montos posibles: NUNCA elegir en silencio (TC-06).
  confianzaMonto = 0.40;
  motivoConfirmacion = 'multiples montos detectados';
}

// ---------- FECHA ----------
const hoy = DateTime.now().setZone(ZONA).startOf('day');
let fecha = hoy;
let confianzaFecha = 0.90;

const DIAS = { lunes:1, martes:2, miercoles:3, jueves:4, viernes:5, sabado:6, domingo:7 };

if (/\bantier|anteayer\b/.test(t)) {
  fecha = hoy.minus({ days: 2 });
} else if (/\bayer\b/.test(t)) {
  fecha = hoy.minus({ days: 1 });
} else if (/\bhoy\b/.test(t)) {
  fecha = hoy;
} else if ((m = t.match(/hace\s+(\d+)\s+dias?/))) {
  fecha = hoy.minus({ days: parseInt(m[1], 10) });
} else if (/semana pasada/.test(t)) {
  fecha = hoy.minus({ weeks: 1 }).startOf('week');
  confianzaFecha = 0.60;  // ambiguo: se pedira confirmacion
} else if ((m = t.match(/\b(lunes|martes|miercoles|jueves|viernes|sabado|domingo)\b/))) {
  const objetivo = DIAS[m[1]];
  let d = hoy;
  for (let i = 1; i <= 7; i++) {  // ocurrencia mas reciente en el pasado
    d = hoy.minus({ days: i });
    if (d.weekday === objetivo) break;
  }
  fecha = d;
} else if ((m = t.match(/\bel\s+(\d{1,2})\b(?!\s*(?:mil|k))/))) {
  const dia = parseInt(m[1], 10);
  if (dia >= 1 && dia <= 31) {
    const esteMes = hoy.set({ day: Math.min(dia, hoy.daysInMonth) });
    fecha = esteMes <= hoy ? esteMes : hoy.minus({ months: 1 }).set({ day: Math.min(dia, hoy.minus({ months: 1 }).daysInMonth) });
  }
}

// ---------- TIPO ----------
let tipo = 'gasto';
let intencion = 'registrar_gasto';
if (/me devolvieron|me reembolsaron|reversaron|devolucion|reembolso/.test(t)) {
  tipo = 'reembolso'; intencion = 'registrar_reembolso';
} else if (/me pagaron|recibi|me consignaron|me entro|nomina|quincena/.test(t)) {
  tipo = 'ingreso'; intencion = 'registrar_ingreso';
} else if (/entre cuentas|traslade|pase de ahorros/.test(t)) {
  tipo = 'traslado'; intencion = 'registrar_gasto';
}

// ---------- METODO DE PAGO ----------
let metodoPago = 'no_especificado';
for (const [k, v] of Object.entries({ efectivo: 'efectivo', debito: 'debito', credito: 'credito', tarjeta: 'credito', transferencia: 'transferencia', nequi: 'nequi', daviplata: 'daviplata' })) {
  if (new RegExp(`\\b${k}\\b`).test(t)) { metodoPago = v; break; }
}

return [{
  json: {
    ...sobre,
    pre: {
      texto_limpio: t,
      texto_original: textoOriginal,
      monto,
      candidatos_monto: unicos,
      confianza_monto: confianzaMonto,
      jerga,
      fecha_movimiento: fecha.toISODate(),
      confianza_fecha: confianzaFecha,
      tipo,
      intencion,
      metodo_pago: metodoPago,
      motivo_confirmacion: motivoConfirmacion
    }
  }
}];

// Capa 1 de la cadena de clasificacion (prompts/categorization.md):
// palabra clave exacta desde la hoja Categorias.
// Coincidencia por palabra completa: "gas" no debe dispararse dentro
// de "gaseosa". Gana la palabra clave mas larga.

const sobre = $('Pre-normalizar').first().json;
const categorias = $input.all()
  .map(i => i.json)
  .filter(c => c && c.categoria_id && String(c.activa).toUpperCase() === 'TRUE');

const texto = sobre.pre.texto_limpio;

function normaliza(s) {
  return String(s || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}

let mejor = null;
let largoMejor = 0;

for (const c of categorias) {
  const claves = normaliza(c.palabras_clave).split('|').map(k => k.trim()).filter(Boolean);
  for (const k of claves) {
    const escapada = k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const re = new RegExp(`(^|[^a-z0-9])${escapada}([^a-z0-9]|$)`);
    if (re.test(texto) && k.length > largoMejor) {
      largoMejor = k.length;
      mejor = { categoria_id: c.categoria_id, nombre: c.nombre, clave: k };
    }
  }
}

// Catalogo compacto para el prompt del LLM, si hace falta llamarlo.
const listaCategorias = categorias
  .map(c => `${c.categoria_id} | ${c.nombre} | ${c.palabras_clave || ''}`)
  .join('\n');

const confianzaCat = mejor ? 0.95 : 0;
const confianza = Math.min(
  sobre.pre.confianza_monto,
  confianzaCat || 1,
  sobre.pre.confianza_fecha
);

// Solo se salta el LLM si TODO esta resuelto con holgura.
const resueltoSinIA =
  sobre.pre.monto !== null &&
  mejor !== null &&
  sobre.pre.confianza_monto >= 0.90 &&
  sobre.pre.confianza_fecha >= 0.90;

return [{
  json: {
    ...sobre,
    catalogo: { lista: listaCategorias, total: categorias.length },
    keyword: mejor,
    _confianza_reglas: resueltoSinIA ? confianza : 0,
    _resuelto_sin_ia: resueltoSinIA
  }
}];

